export function assertKnowledgeCatalog(data) {
  const actualCards = data.deck.map((item) => item.id);
  const actualQuestions = data.categories.flatMap((category) => category.questions.map((item) => item.id));
  const actualSpreads = data.spreads.map((item) => item.id);
  if (JSON.stringify(actualCards) !== JSON.stringify(CARD_IDS)) throw new Error("Generated card catalog is stale.");
  if (JSON.stringify(actualQuestions) !== JSON.stringify(QUESTION_IDS)) throw new Error("Generated question catalog is stale.");
  if (JSON.stringify(actualSpreads) !== JSON.stringify(SPREAD_IDS)) throw new Error("Generated spread registry is stale.");
  if (CARD_CATALOG.length !== CARD_IDS.length || QUESTION_CATALOG.length !== data.categories.length) {
    throw new Error("Generated lightweight catalogs are incomplete.");
  }
  return true;
}
